 async function request(path,{method='GET',body}={}){const headers={};let serialized;if(body!==undefined){serialized=JSON.stringify(body);if(new Blob([serialized]).size>8*1024*1024)throw Error('Permintaan terlalu besar (maksimal 8 MB termasuk data JSON). Kurangi jumlah atau ukuran lampiran.');headers['Content-Type']='application/json';const session=await window.ZentixSession;headers['x-csrf-token']=session.csrf;}const response=await fetch(API+path,{method,headers,cache:'no-store',...(body!==undefined?{body:serialized}:{})});const payload=await response.json().catch(()=>({}));if(!response.ok){const error=Error(payload.error||(response.status===413?'Permintaan terlalu besar. Kurangi jumlah atau ukuran lampiran.':'Permintaan Message Studio gagal.'));error.code=payload.code;error.uncertain=payload.uncertain===true;throw error;}return payload;}
 function documentUploads(){const needed=new Set();for(const block of [...list(state.doc.before),...list(state.doc.containers).flatMap(c=>list(c.blocks)),...list(state.doc.after)]){if(block.type==='file'&&block.source?.kind==='upload')needed.add(block.source.uploadId);if(block.type==='media'||block.type==='section')for(const item of list(block.items))if(item.source?.kind==='upload')needed.add(item.source.uploadId);}for(const id of state.uploads.keys())if(!needed.has(id))state.uploads.delete(id);return [...state.uploads.values()].map(({id,name,mime,base64})=>({id,name,mime,base64}));}
