 function documentValidLocally(){return state.doc?.version===1&&Array.isArray(state.doc.containers)&&(state.doc.containers.length||list(state.doc.before).length||list(state.doc.after).length);}
 function topEntries(doc){return [...list(doc.before).map(x=>({kind:'block',id:x.id})),...list(doc.containers).map(x=>({kind:'container',id:x.id})),...list(doc.after).map(x=>({kind:'block',id:x.id}))];}
 function validOrder(doc){if(doc.order===undefined)return true;if(!Array.isArray(doc.order))return false;const entries=topEntries(doc),keys=new Set(entries.map(e=>`${e.kind}:${e.id}`));if(keys.size!==entries.length||doc.order.length!==keys.size)return false;return doc.order.every(e=>e&&Object.keys(e).length===2&&keys.delete(`${e.kind}:${e.id}`));}
 function syncOrder(){const entries=topEntries(state.doc),available=new Map(entries.map(e=>[`${e.kind}:${e.id}`,e]));if(!Array.isArray(state.doc.order))state.doc.order=entries;else{state.doc.order=state.doc.order.filter(e=>available.has(`${e.kind}:${e.id}`));const seen=new Set(state.doc.order.map(e=>`${e.kind}:${e.id}`));for(const entry of entries)if(!seen.has(`${entry.kind}:${entry.id}`))state.doc.order.push(entry);}return state.doc.order;}
 function moveTop(kind,id,delta){const order=syncOrder(),index=order.findIndex(e=>e.kind===kind&&e.id===id),target=index+delta;if(index<0||target<0||target>=order.length)return;[order[index],order[target]]=[order[target],order[index]];}
 function drawOrder(root,box){const order=syncOrder(),section=el('section',{className:'ms-container-node ms-order-list'});section.append(el('div',{className:'ms-order-title',text:'URUTAN PESAN'}),el('p',{className:'ms-empty',text:'Atur urutan komponen di luar container dengan tombol panah.'}));order.forEach((entry,index)=>{const ci=state.doc.containers.findIndex(c=>c.id===entry.id),block=[...list(state.doc.before),...list(state.doc.after)].find(b=>b.id===entry.id),title=entry.kind==='container'?`Container ${ci+1}`:componentName(block);const row=el('div',{className:'ms-order-row'}),name=el('span',{text:`${index+1}. ${title}`});const up=button('↑','ms-mini',()=>{moveTop(entry.kind,entry.id,-1);drawEditor(root);setStatus(root,'Urutan belum disimpan.');}),down=button('↓','ms-mini',()=>{moveTop(entry.kind,entry.id,1);drawEditor(root);setStatus(root,'Urutan belum disimpan.');});up.disabled=index===0;down.disabled=index===order.length-1;up.setAttribute('aria-label',`Pindahkan ${title} urutan ${index+1} ke atas`);down.setAttribute('aria-label',`Pindahkan ${title} urutan ${index+1} ke bawah`);row.append(name,up,down);section.append(row);});box.append(section);}
