 function addBlock(kind){const {container}=selected();if(container.blocks.length>=10)return;const id=`${kind}-${localId()}`;let block={id,type:kind};if(kind==='text')block.content='Tulis teks di sini.';if(kind==='separator'){block.divider=true;block.spacing=1;}if(kind==='section')block.content='Tulis teks section di sini.';if(kind==='media'||kind==='section')block.items=[{id:`image-${localId()}`,source:{kind:'url',url:''},description:null,spoiler:false}];if(kind==='buttons')block.buttons=[{id:`button-${localId()}`,label:'Buka link',style:'link',url:'https://example.com',emoji:null,disabled:false}];if(kind==='select')block={id,type:'select',placeholder:'Pilih informasi',minValues:1,maxValues:1,options:[{id:`option-${localId()}`,label:'Pilihan satu',description:null,emoji:null,response:'Respons untuk pilihan ini.'}]};container.blocks.push(block);state.selection={kind:'block',container:state.selection.container,block:container.blocks.length-1};}
