 document.addEventListener('click',event=>{document.querySelectorAll('.ms-color-control').forEach(control=>{if(!control.contains(event.target)){const panel=control.querySelector('.ms-color-panel'),toggle=control.querySelector('.ms-color-toggle');if(panel&&!panel.hidden){panel.hidden=true;toggle?.setAttribute('aria-expanded','false')}}})});
 function colorInput(value,change){value=typeof value==='string'&&/^#[0-9a-f]{6}$/i.test(value)?value:null;const wrap=el('div',{className:'ms-color-control'}),toggle=button('','f-outline ms-color-toggle',()=>{const opening=panel.hidden;panel.hidden=!opening;toggle.setAttribute('aria-expanded',String(opening));});toggle.setAttribute('aria-expanded','false');wrap.addEventListener('keydown',event=>{if(event.key==='Escape'&&!panel.hidden){event.preventDefault();panel.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.focus();}});const swatch=el('span',{className:'ms-color-swatch'}),summary=el('span',{text:value||'Tanpa warna'});swatch.style.backgroundColor=value||'transparent';toggle.append(swatch,summary);const panel=el('div',{className:'ms-color-panel',hidden:true});if(window.ZentixGreetingColor){panel.innerHTML=window.ZentixGreetingColor.render(value||'', '#5865f2',{name:'studioColor',optional:true,embedded:true});const source=panel.querySelector('.greeting-color-source');window.ZentixGreetingColor.bind(panel);source.addEventListener('input',()=>{const next=source.value||null;swatch.style.backgroundColor=next||'transparent';summary.textContent=next?next.toUpperCase():'Tanpa warna';change(next?next.toUpperCase():null);});}else{panel.append(el('p',{text:'Pemilih warna tidak termuat. Muat ulang halaman.'}));}wrap.append(toggle,panel);return wrap;}

