 function drawPreview(root){const box=$('#msPreview',root);if(!box)return;box.replaceChildren();const intro=el('div',{className:'ms-discord-head'},el('div',{className:'ms-discord-avatar',text:state.delivery.sender==='webhook'?(state.delivery.identity.name||'W').slice(0,1).toUpperCase():'✳'}),el('div',null,el('div',{className:'ms-discord-name',text:state.delivery.sender==='webhook'?(state.delivery.identity.name||'Webhook Zentix'):'ZentixBot'},el('small',{text:'BOT'})),el('div',{className:'ms-discord-time',text:'Hari ini · preview container'})));box.append(intro);for(const entry of syncOrder()){if(entry.kind==='block'){const block=[...list(state.doc.before),...list(state.doc.after)].find(item=>item.id===entry.id);if(block)drawOutsidePreview(box,[block]);continue;}const container=state.doc.containers.find(item=>item.id===entry.id);if(!container)continue;const card=el('div',{className:'ms-discord-container'});card.style.borderLeftColor=container.accentColor||'transparent';for(const block of container.blocks){if(block.type==='text')card.append(markdownText(block.content));else if(block.type==='file')card.append(previewFile(block));else if(block.type==='separator')card.append(el('hr',{className:`ms-discord-separator${block.spacing===2?' large':''}`}));else if(block.type==='section'){const section=el('div',{className:'ms-discord-section'},markdownText(block.content));const item=block.items[0],source=safeImage(item?.source);if(source){section.append(previewImage(item,source,true));}card.append(section);}else if(block.type==='media'){const gallery=el('div',{className:'ms-discord-gallery'});for(const item of block.items){const source=safeImage(item.source);if(source){gallery.append(previewImage(item,source));}else gallery.append(el('div',{className:'ms-empty',text:'Gambar belum dipilih.'}));}card.append(gallery);}else if(block.type==='buttons'){const row=el('div',{className:'ms-discord-buttons'});for(const item of block.buttons)row.append(previewButton(item));card.append(row);}else if(block.type==='select'||block.type==='entity-select'){const menu=el('select',{className:'ms-discord-select',disabled:true});menu.append(el('option',{text:block.placeholder||'Pilih…'}));for(const item of list(block.options))menu.append(el('option',{text:`${item.emoji?item.emoji+' ':''}${item.label||'Pilihan'}`}));card.append(menu);}}box.append(card);}}
 function drawOutsidePreview(box,blocks){for(const block of list(blocks)){if(block.type==='text')box.append(markdownText(block.content,'ms-outside-text'));else if(block.type==='file')box.append(previewFile(block));else if(block.type==='separator')box.append(el('hr',{className:`ms-discord-separator${block.spacing===2?' large':''}`}));else if(block.type==='media'){const gallery=el('div',{className:'ms-discord-gallery'});for(const item of block.items){const source=safeImage(item.source);if(source)gallery.append(previewImage(item,source));else gallery.append(el('div',{className:'ms-empty',text:'Gambar belum dipilih.'}));}box.append(gallery);}else if(block.type==='buttons'){const row=el('div',{className:'ms-discord-buttons ms-outside-buttons'});for(const item of block.buttons)row.append(previewButton(item));box.append(row);}else if(block.type==='select'||block.type==='entity-select'){const menu=el('select',{className:'ms-discord-select',disabled:true});menu.append(el('option',{text:block.placeholder||'Pilih…'}));for(const item of list(block.options))menu.append(el('option',{text:`${item.emoji?item.emoji+' ':''}${item.label||'Pilihan'}`}));box.append(menu);}}}
